      "favorited" : false,
      "full_text" : "Usar aria-label para rotular botões, links e outros elementos focáveis pode ser uma alternativa. \n\nPorém evito ao máximo. +",
      "lang" : "pt",
      "in_reply_to_screen_name" : "obrunopulis",
      "in_reply_to_user_id_str" : "1003769356462051328"
